def generate_xlsx(output_path):
    wb = Workbook()
    ws = wb.active
    ws.title = "TestPlan"

    # Header styling
    header_font = Font(name="Calibri", bold=True, color="FFFFFF", size=11)
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    header_align = Alignment(horizontal="center", vertical="center", wrap_text=True)
    cell_align = Alignment(vertical="top", wrap_text=True)
    thin_border = Border(
        left=Side(style="thin"), right=Side(style="thin"),
        top=Side(style="thin"), bottom=Side(style="thin")
    )

    # Write headers
    for col_idx, col_name in enumerate(COLUMNS, 1):
        cell = ws.cell(row=1, column=col_idx, value=col_name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = header_align
        cell.border = thin_border
        ws.column_dimensions[get_column_letter(col_idx)].width = COL_WIDTHS.get(col_name, 15)

    # Write data rows
    for row_idx, tc in enumerate(TEST_CASES, 2):
        for col_idx, col_name in enumerate(COLUMNS, 1):
            val = tc.get(col_name, "")
            cell = ws.cell(row=row_idx, column=col_idx, value=val)
            cell.alignment = cell_align
            cell.border = thin_border

    # Freeze first row
    ws.freeze_panes = "A2"

    # MetaData sheet (very hidden)
    ws_meta = wb.create_sheet(title="MetaData")
    ws_meta.sheet_state = "veryHidden"
    now_ist = datetime.now(IST)
    meta_data = [
        ["Property", "Value"],
        ["IP_Name", "GPIO"],
        ["Test_Case_Name", "gpio_reg_wr_rd_test"],
        ["Total_Test_Cases", len(TEST_CASES)],
        ["Generated_Timestamp_IST", now_ist.strftime("%Y-%m-%d %H:%M:%S IST")],
        ["Generator", "Ag_Excel_Generator Agent"],
        ["Base_Address", "0xA001A000"],
        ["Register_Count", 49],
    ]
    for r_idx, row_data in enumerate(meta_data, 1):
        for c_idx, val in enumerate(row_data, 1):
            cell = ws_meta.cell(row=r_idx, column=c_idx, value=val)
            if r_idx == 1:
                cell.font = Font(bold=True)

    wb.save(output_path)
    print(f"XLSX generated: {output_path}")
    return output_path


def push_to_github(local_path, repo_path, token=None):
    """Push the generated XLSX to GitHub using PyGithub."""
    try:
        from github import Github
    except ImportError:
        print("PyGithub not installed. Install with: pip install PyGithub")
        print(f"Manual upload required: {local_path} -> {repo_path}")
        return None

    if token is None:
        token = os.environ.get("GITHUB_TOKEN")
    if not token:
        print("GITHUB_TOKEN not set. Set environment variable or pass token parameter.")
        print(f"Manual upload required: {local_path} -> {repo_path}")
        return None

    g = Github(token)
    repo = g.get_repo("titusbspgit/PSVValidation")

    with open(local_path, "rb") as f:
        content = f.read()

    try:
        repo.create_file(
            path=repo_path,
            message=f"Add GPIO TestPlan XLSX - auto-generated",
            content=content,
            branch="main"
        )
        url = f"https://github.com/titusbspgit/PSVValidation/blob/main/{repo_path}"
        print(f"Pushed to GitHub: {url}")
        return url
    except Exception as e:
        print(f"GitHub push failed: {e}")
        return None


if __name__ == "__main__":
    now_ist = datetime.now(IST)
    filename = f"GPIO_TestPlan_{now_ist.strftime('%Y%m%d')}_{now_ist.strftime('%H%M%S')}.xlsx"
    local_path = filename
    repo_path = f"Test_Output/GPIO/TestPlan/{filename}"

    generate_xlsx(local_path)
    url = push_to_github(local_path, repo_path)

    if url:
        print(json.dumps({"status": "SUCCESS", "execution_mode": "Fallback Automation", "output_file_path": repo_path, "github_url": url}, indent=2))
    else:
        print(json.dumps({"status": "PARTIAL", "execution_mode": "Fallback Automation", "output_file_path": local_path, "github_url": "Manual upload required"}, indent=2))
